import {put,get} from './store.js';
let registration;
async function worker(){if(!('serviceWorker'in navigator)||!('caches'in window)||!window.isSecureContext)throw new Error('Este navegador no permite verificar el modo sin conexión.');registration ||= await navigator.serviceWorker.register('./sw.js',{scope:'./'});const reg=await Promise.race([navigator.serviceWorker.ready,new Promise((_,reject)=>setTimeout(()=>reject(new Error('El navegador no activó la PWA. Abre el enlace directamente y vuelve a intentar.')),10000))]);return reg.active}
function message(sw,type){return new Promise((resolve,reject)=>{const channel=new MessageChannel();const timer=setTimeout(()=>reject(new Error('La preparación tardó demasiado. Puedes reintentar.')),30000);channel.port1.onmessage=e=>{clearTimeout(timer);e.data.ok?resolve(e.data):reject(new Error(e.data.error))};sw.postMessage({type},[channel.port2])})}
export async function prepareOffline(){await put('meta',{id:'offline',status:'downloading'});try{const sw=await worker();const result=await message(sw,'DOWNLOAD');await put('meta',{id:'offline',status:'ready',version:result.version,verifiedAt:new Date().toISOString(),count:result.count});return result}catch(e){await put('meta',{id:'offline',status:'failed',error:e.message});throw e}}
export async function verifyOffline(){const state=await get('meta','offline');if(!state||state.status!=='ready')return false;try{const sw=await worker();await message(sw,'VERIFY');return true}catch{return false}}
export async function requestPersistence(){return navigator.storage?.persist?await navigator.storage.persist():false}
